const targets = await (await fetch('http://localhost:9222/json/list')).json();
const target = targets.find((item) => item.url.includes('/api/css/segmented-control'));
if (!target) throw new Error('segmented page not found');
const socket = new WebSocket(target.webSocketDebuggerUrl);
let id = 0;
const call = (method, params = {}) => new Promise((resolve, reject) => {
  const requestId = ++id;
  const listener = (event) => {
    const message = JSON.parse(event.data);
    if (message.id !== requestId) return;
    socket.removeEventListener('message', listener);
    if (message.error) reject(message.error); else resolve(message.result);
  };
  socket.addEventListener('message', listener);
  socket.send(JSON.stringify({ id: requestId, method, params }));
});
socket.addEventListener('open', async () => {
  await call('Runtime.enable');
  const expression = `(() => {
    const root = document.querySelector('.instui-segmented-control');
    if (!root) return { error: 'no segmented control' };
    const labels = [...root.querySelectorAll(':scope > label')];
    const start = root.querySelector(':scope > .overflow-start');
    const end = root.querySelector(':scope > .overflow-end');
    return {
      root: { clientWidth: root.clientWidth, scrollWidth: root.scrollWidth, scrollLeft: root.scrollLeft, rect: root.getBoundingClientRect().toJSON() },
      labels: labels.map((label) => ({ text: label.textContent.trim(), rect: label.getBoundingClientRect().toJSON(), checked: label.querySelector('input')?.checked })),
      start: { hidden: start?.hidden, rect: start?.getBoundingClientRect().toJSON() },
      end: { hidden: end?.hidden, rect: end?.getBoundingClientRect().toJSON() },
      scripts: [...document.scripts].map((script) => script.src).filter(Boolean).filter((src) => src.includes('interactions'))
    };
  })()`;
  const result = await call('Runtime.evaluate', { expression, returnByValue: true, awaitPromise: true });
  console.log(JSON.stringify(result.result.value, null, 2));
  socket.close();
});
